"""Write telemetria.toml next to the built Telemetria.exe (called by build_exe.bat).

The repo's telemetria.toml stays the one to edit: it is copied on every build, and `app_root` is pinned
to the repo's library (absolute) unless the repo toml sets it, so the exe works on the same `data/`.
"""

import sys
import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main(out_dir: Path) -> None:
    src = ROOT / "telemetria.toml"
    text = src.read_text(encoding="utf-8") if src.exists() else ""
    raw = tomllib.loads(text)
    lines = [
        "# GENERATED by build_exe.bat from the repo's telemetria.toml: edit that one, this copy is replaced on every build.",
        text.rstrip(),
    ]
    if "app_root" in raw:
        root = Path(raw["app_root"])
        if not root.is_absolute():  # relative to the repo toml: make it absolute for the exe folder
            text_lines = [ln for ln in text.splitlines() if not ln.strip().startswith("app_root")]
            lines = lines[:1] + ["\n".join(text_lines).rstrip(), f'app_root = "{(ROOT / root).resolve().as_posix()}"']
    else:
        lines.append(f'app_root = "{ROOT.as_posix()}"   # the library this exe uses')
    out = out_dir / "telemetria.toml"
    out.write_text("\n".join(ln for ln in lines if ln) + "\n", encoding="utf-8")
    print(f"wrote {out}")


if __name__ == "__main__":
    main(Path(sys.argv[1]))
